        `[overpass] Fetching Overpass API (attempt ${attempt + 1}/${maxAttempts}) via ${endpoint}`
      );
      onStatus("Querying OpenStreetMap (Overpass)…");
      const res = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
